import itertools

def has_distinct_nonzero_digits(m):
    s = str(m)
    digits = [int(d) for d in s]

    # Check for nonzero
    if 0 in digits:
        return False

    # Check for distinct
    return len(digits) == len(set(digits))

# Cache for memoization (optional but good practice for recursion)
good_cache = {}

def is_good(m):
    if m in good_cache:
        return good_cache[m]

    # Base case: Single-digit numbers are good
    if m < 10:
        return True

    # Constraint check: must have distinct nonzero digits
    if not has_distinct_nonzero_digits(m):
        # If the current number doesn't meet the basic structural requirement, 
        # it cannot be good by definition.
        return False

    s = str(m)
    digits = [int(d) for d in s]

    # Recursive check: Remove one digit and check conditions
    for i in range(len(digits)):
        # Construct the divisor d by removing the i-th digit
        d_str = s[:i] + s[i+1:]
        try:
            d = int(d_str)
        except ValueError:
            # Should not happen for m > 9
            continue

        # Check 1: d must divide m
        if m % d == 0:
            # Check 2: d must be good
            if is_good(d):
                good_cache[m] = True
                return True

    # If no digit removal satisfies the conditions
    good_cache[m] = False
    return False

